// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(address player) public {
        // Ensure player has not wagered (wagers[player] == 0)
        vm.assume(player != address(0));
        // Call AdjustBetAmounts to satisfy the entry point requirement
        c.AdjustBetAmounts(100);
        // After adjusting, assert that a non-wagered player returns false
        assertTrue(!c.hasPlayerWagered(player));
    }
}

